#include <Adafruit_GFX.h>
#include <Adafruit_ST7789.h>

#define LCD_CS   15
#define LCD_DC    2
#define LCD_RST   4
#define LCD_BLK  32

Adafruit_ST7789 tft(LCD_CS, LCD_DC, LCD_RST);

void setup() {
  pinMode(LCD_BLK, OUTPUT);
  digitalWrite(LCD_BLK, HIGH);

  tft.init(135, 240);
  tft.setRotation(1);
  tft.fillScreen(ST77XX_BLUE);
  tft.setTextColor(ST77XX_WHITE);
  tft.setTextSize(2);
  tft.setCursor(10, 40);
  tft.println("HOLA!");
}

void loop() {}
